font-family: gulimChe; font-size: 10pt;\">&nbsp; &nbsp; &nbsp; &nbsp;SUM(A.STOCK_QTY) AS STOCK_QTY_SUM ,</span></p>  <p><span style=\"font-family: gulimChe; font-size: 10pt;\">&nbsp; &nbsp; &nbsp; &nbsp;MAX(CASE WHEN A.CODE_NM ='울산공장' &nbsp;THEN &nbsp; &nbsp; &nbsp;'울산공장 ' &nbsp;||A.STOCK_QTY||' ; ' &nbsp;ELSE NULL END) A01 ,</span></p>  <p><span style=\"font-family: gulimChe; font-size: 10pt;\">&nbsp; &nbsp; &nbsp; &nbsp;MAX(CASE WHEN A.CODE_NM ='전주1공장' THEN &nbsp; &nbsp; &nbsp;'전주1공장 ' ||A.STOCK_QTY||' ; ' &nbsp;ELSE NULL END) A11 ,</span></p>  <p><span style=\"font-family: gulimChe; font-size: 10pt;\">&nbsp; &nbsp; &nbsp; &nbsp;MAX(CASE WHEN A.CODE_NM ='전주2공장' THEN &nbsp; &nbsp; &nbsp;'전주2공장 ' ||A.STOCK_QTY||' ; ' &nbsp;ELSE NULL END) A02 ,</span></p>  <p><span style=\"font-family: gulimChe; font-size: 10pt;\">&nbsp; &nbsp; &nbsp; &nbsp;MAX(CASE WHEN A.CODE_NM ='전주3공장' THEN &nbsp; &nbsp; &nbsp;'전주3공장 ' ||A.STOCK_QTY||' ; ' &nbsp;ELSE NULL END) A03 ,</span></p>  <p><span style=\"font-family: gulimChe; font-size: 10pt;\">&nbsp; &nbsp; &nbsp; &nbsp;MAX(C",
