			"NTT_TITLE": "DB 반영 요청건 처리 (10월 4주차)",
			"NTT_CNTS": "<p><span style=\"font-family: gulimChe;\">-- 2016.10.28 신진호DR 요청</span></p>  <p><span style=\"font-family: gulimChe;\">DROP DATABASE LINK KQIS_NEOSYS_IF;</span></p>  <p><span style=\"font-family: gulimChe;\">DROP DATABASE LINK KQIS_NEOQMS_IF;</span></p>  <p><span style=\"font-family: gulimChe;\">DROP DATABASE LINK KQIS_NEOPMS_IF;</span></p>  <p><span style=\"font-family: gulimChe;\">create database link KQIS_NEOSYS_IF CONNECT TO NEOTIDE_SYS IDENTIFIED BY \"QIS3480\" USING 'IDMS';</span></p>  <p><span style=\"font-family: gulimChe;\">create database link KQIS_NEOQMS_IF CONNECT TO NEOTIDE_QMS IDENTIFIED BY \"QIS3480\" USING 'IDMS';</span></p>  <p><span style=\"font-family: gulimChe;\">create database link KQIS_NEOPMS_IF CONNECT TO NEOTIDE_PMS IDENTIFIED BY \"QIS3480\" USING 'IDMS';</span></p>  <p><span style=\"font-family: gulimChe;\"><br></span></p>  <p><span style=\"font-family: gulimChe;\">-- 2016.10.28 최원범SW 요청</span></p>  <p><span style=\"font-family: gulimChe;\">ALTER TABLE OIUSER.TS04C_PUR_COST_MAST MODIFY",
			"NTT_CNTS_DESC": " INVOICE_NO VARCHAR2(50);</span></p>  <p><span style=\"font-family: gulimChe;\"><br></span></p>  <p><span style=\"font-family: gulimChe;\">-- 2016.10.27 원도석SW 요청</span></p>  <p><span style=\"font-family: gulimChe;\">ALTER TABLE KAIS.TF06_RENT ADD MNG_EMP VARCHAR2(8);</span></p>  <p><span style=\"font-family: gulimChe;\"><br></span></p>  <p><span style=\"font-family: gulimChe;\">-- 2016.10.27 심승철DR 요청</span></p>  <p><span style=\"font-family: gulimChe;\">GRANT SELECT ON APISADMIN.MG_TASK_CD_CONV TO KAIS_SELECT_FOR_PUB;</span></p>  <p><span style=\"font-family: gulimChe;\">GRANT SELECT ON APISADMIN.MG_TECH_CD_CONV TO KAIS_SELECT_FOR_PUB;</span></p>  <p><span style=\"font-family: gulimChe;\"><br></span></p>  <p><span style=\"font-family: gulimChe;\">-- 2016.10.27 전상우GJ 요청</span></p>  <p><span style=\"font-family: gulimChe;\">CREATE OR REPLACE VIEW KAIS.VH01_DEPT_HIST AS&nbsp;</span></p>  <p><span style=\"font-family: gulimChe;\">WITH T AS (</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; SELECT</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; &nbsp; CT.REMARK6 AS COMP</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , DT.DEPT AS DEPT_CD</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , DT.FULL_DEPT_NM AS DEPT_NM</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , DT.DEPT_NM_ENG</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , (SELECT DEPT FROM TH01_DEPT WHERE SEQ_DEPT = OG.UP_SEQ_DEPT) AS UPPER_DEPT</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , SYS_CONNECT_BY_PATH(LPAD(TO_CHAR(OG.LEVEL_SEQ),3,'0'),'|') AS SORT_KEY</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , DT.FROM_DATE</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , DT.TO_DATE</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , ROW_NUMBER() OVER(PARTITION BY DT.DEPT, DT.FROM_DATE ORDER BY DT.TO_DATE DESC) AS RK</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , 'Y' AS USE_YN</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; FROM TH01_DEPT DT</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; LEFT JOIN TH01_ORGAN OG ON DT.SEQ_DEPT = OG.SEQ_DEPT</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; LEFT JOIN TC00_CODE_LIST CT ON CT.CODE_GROUP='CORP' AND CT.CODE_NM = DT.CORP &nbsp;</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; WHERE 1=1</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; AND DT.DEPT IS NOT NULL</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; AND DT.FROM_DATE &lt; DT.TO_DATE</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; AND DT.CORP IN ('(주)TEST','Europe','Basildon','(America)')</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; START WITH OG.UP_SEQ_DEPT IS NULL</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; CONNECT BY OG.UP_SEQ_DEPT = PRIOR OG.SEQ_DEPT</span></p>  <p><span style=\"font-family: gulimChe;\">)</span></p>  <p><s",
