			"NTT_TITLE": "하반기 서버패스워드 변경",
			"NTT_CNTS": "<p><span style=\"font-size: 11pt;\">보안팀은</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> '</span><strong><span style=\"font-family: 굴림; font-size: 11pt;\">미래창조과학부</span></strong><span style=\"font-family: gulimChe,serif; font-size: 11pt;\">' </span><span style=\"font-size: 11pt;\">정보보안</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">패스워드</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">관련</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">조항에</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">맞춰</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">하반기</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">서버</span><span style=\"font-family: gulimChe,serif; fo",
			"NTT_CNTS_DESC": "nt-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">패스워드</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">변경을</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">진행하고자</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> </span><span style=\"font-size: 11pt;\">합니다</span><span style=\"font-family: gulimChe,serif; font-size: 11pt;\">. </span></p>  <p><span style=\"font-family: gulimChe,serif; font-size: 11pt;\"> <br></span></p>  <p><strong><span style=\"color: darkblue; font-family: gulimChe,serif; font-size: 11pt;\">&lt;</span></strong><strong><span style=\"color: darkblue; font-family: 굴림; font-size: 11pt;\">서버</span></strong><strong><span style=\"color: darkblue; font-family: gulimChe,serif; font-size: 11pt;\"> </span></strong><strong><span style=\"color: darkblue; font-family: 굴림; font-size: 11pt;\">패스워드</span></strong><strong><span style=\"color: darkblue; font-family: gulimChe,serif; font-size: 11pt;\">&nbsp;</span></strong><strong><span style=\"color: darkblue; font-family: 굴림; font-size: 11pt;\">관리</span></strong><strong><span style=\"color: darkblue; font-family: gulimChe,serif; font-size: 11pt;\"> </span></strong><strong><span style=\"color: darkblue; font-family: 굴림; font-size: 11pt;\">정책</span></strong><strong><span style=\"color: darkblue; font-family: gulimChe,serif; font-size: 11pt;\">&gt;</span></strong></p>  <table style=\"width: 598px; border-collapse: collapse;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">   <tbody>  <tr style=\"height: 18px;\">   <td style=\"background: rgb(102, 255, 255); padding: 0px; border: 1px solid black; border-image: none; width: 72px; height: 18px;\">   <p align=\"center\" style=\"text-align: center;\"><b><span style=\"font-size: 11pt;\">구</span></b><b><span style=\"font-family: gulimChe,serif; font-size: 11pt;\">&nbsp;&nbsp;&nbsp;&nbsp; </span></b><b><span style=\"font-size: 11pt;\">분</span></b></p> </td>   <td style=\"background: rgb(102, 255, 255); border-width: 1px 1px 1px 0px; border-style: solid solid solid none; border-color: black black black rgb(0, 0, 0); padding: 0px; border-image: none; width: 527px; height: 18px;\">   <p align=\"center\" style=\"text-align: center;\"><b><span style=\"font-size: 11pt;\">내</span></b><b><span style=\"font-family: gulimChe,serif; font-size: 11pt;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></b><b><span style=\"font-size: 11pt;\">용</span></b></p> </td>   </tr>   <tr style=\"height: 51px;\">   <td style=\"background: rgb(102, 255, 255); border-width: 0px 1px 1px; border-style: none solid solid; border-color: rgb(0, 0, 0) black black; padding: 0px; border-image: none; height: 51px;\">   <p align=\"center\" style=\"text-align: center;\"><b><span style=\"font-size: 11pt;\">점검목적</span></b></p> </td>   <td style=\"border-width: 0px 1px 1px 0px; border-style: none solid solid none; border-color: rgb(0, 0, 0) black black rgb(0, 0, 0); padding: 0px; width: 527px; height: 51px; background-color: t",
