			"NTT_TITLE": "DB 반영 요청건 처리 (10월 3주차)",
			"NTT_CNTS": "<p><span style=\"font-family: gulimChe;\"><br></span></p>  <p><span style=\"font-family: gulimChe;\">-- 2016.10.21 윤영준DR 요청</span></p>  <p><span style=\"font-family: gulimChe;\">CREATE OR REPLACE VIEW KAIS.VS02_SMB_ITEMS_DESCR</span></p>  <p><span style=\"font-family: gulimChe;\">AS</span></p>  <p><span style=\"font-family: gulimChe;\">SELECT&nbsp;</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; CAL.COM_BASE_SEQ</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,CAL.MAIN_ITEMS_NM</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,CAL.ITEMS_DESCR</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,CAL.ITEMS_OUT_LINE</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,CAL.ITEMS_DTL_CONT</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,CAL.CONST_METH</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,CAL.NOTICE</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,CAL.REMARK</span></p>  <p><span style=\"font-family: gulimChe;\">&n",
			"NTT_CNTS_DESC": "bsp; ,CAL.COL_LANG</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,'' AS ITEMS_LIST</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,CB.ITEMS</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,FS02_SMB_EXIST_ITEMS_ATTRIB ( CB.COM_BASE_SEQ, '신상품') AS NEW_ITEM</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,FS02_SMB_EXIST_ITEMS_ATTRIB ( CB.COM_BASE_SEQ, '베스트상품') AS BEST_ITEM</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,FS02_SMB_EXIST_ITEMS_ATTRIB ( CB.COM_BASE_SEQ, '친환경') AS GREEN_ITEM</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,FS02_SMB_EXIST_ITEMS_ATTRIB ( CB.COM_BASE_SEQ, '에너지절감(단열)') AS ENERGY_ITEM</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,FS02_SMB_EXIST_ITEMS_ATTRIB ( CB.COM_BASE_SEQ, 'DIY') AS DIY_ITEM</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,(SELECT MIN(ATTFILE_PATH) FROM TS02_SMB_ATTFILE WHERE ATTFILE_NO IN( (SELECT RELATION_CD FROM TS02_SMB_ITEMS_RELATION Z WHERE Z.ITEMS = CB.ITEMS AND RELATION_ID='I'))) AS ATTFILE_PATH</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,(SELECT RTRIM(TO_CHAR(PSIZE, 'FM9990D99'), '.') || UNIT &nbsp;FROM VS02_SMB_ITEMS_PRICE Z WHERE Z.ITEMS = CB.ITEMS AND ROWNUM=1) AS PUNIT --규격</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,(SELECT TO_CHAR(ROUND(Z.PRICE), '999,999,999,999,999') FROM VS02_SMB_ITEMS_PRICE Z WHERE Z.ITEMS = CB.ITEMS AND ROWNUM=1) AS PRICE--단가</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,(SELECT COUNT(*) FROM TS02_SMB_ITEM_RHIST Z WHERE Z.COM_BASE_SEQ = CB.COM_BASE_SEQ) AS HIT</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; ,TO_CHAR(CB.INPUT_DATETIME,'YYYYMMDD') AS INPUT_DATE</span></p>  <p><span style=\"font-family: gulimChe;\">FROM&nbsp;</span></p>  <p><span style=\"font-family: gulimChe;\">TS02_SMB_ITEMS_CB_ATTRIB CB</span></p>  <p><span style=\"font-family: gulimChe;\">INNER JOIN&nbsp;</span></p>  <p><span style=\"font-family: gulimChe;\">TS02_SMB_ITEMS_CB_ATT_LANG CAL</span></p>  <p><span style=\"font-family: gulimChe;\">ON CB.COM_BASE_SEQ = CAL.COM_BASE_SEQ</span></p>  <p><span style=\"font-family: gulimChe;\">WHERE CB.ACTIVE_YN = 'Y'</span></p>  <p><span style=\"font-family: gulimChe;\"><br></span></p>  <p><span style=\"font-family: gulimChe;\">-- 2016.10.21 심승철DR 요청 (APIS Data 운영DB로 이관지원)</span></p>  <p><span style=\"font-family: gulimChe;\">-- export</span></p>  <p><span style=\"font-family: gulimChe;\">USERID='/ AS SYSDBA'</span></p>  <p><span style=\"font-family: gulimChe;\">JOB_NAME=apisadmin20161021</span></p>  <p><span style=\"font-family: gulimChe;\">DIRECTORY=BACKUP_DATA_PUMP</span></p>  <p><span style=\"font-family: gulimChe;\">DUMPFILE=apisadmin20161021.dmp</span></p>  <p><span style=\"font-family: gulimChe;\">LOGFILE=apisadmin20161021.log</span></p>  <p><span style=\"font-family: gulimChe;\">TABLES=APISADMIN.TAP_RND_DIVISION,APISADMIN.TAP_RND_DIVISION_MAPPING,APISADMIN.TAP_MST_CASUAL_USER_INFO,APISADMIN.TAP_TASK_EVAL_CLASS,APISADMIN.TAP_TASK_EVAL_C",
