			"NTT_CNTS": "<p><span style=\"font-family: gulimChe;\">-- 2016.10.14 윤영준DR 요청</span></p>  <p><span style=\"font-family: gulimChe;\">ALTER TABLE TS02_SMB_ITEMS_RELATION DROP CONSTRAINT SYS_C00456594;</span></p>  <p><span style=\"font-family: gulimChe;\">ALTER TABLE TS02_SMB_ITEMS_RELATION DROP CONSTRAINT SYS_C00456595;</span></p>  <p><span style=\"font-family: gulimChe;\">ALTER TABLE TS02_SMB_ITEMS_RELATION DROP CONSTRAINT SYS_C00456596;</span></p>  <p><span style=\"font-family: gulimChe;\">ALTER TABLE TS02_SMB_ITEMS_RELATION DROP CONSTRAINT SYS_C00456597;</span></p>  <p><span style=\"font-family: gulimChe;\">ALTER TABLE TS02_SMB_ITEMS_RELATION DROP CONSTRAINT SYS_C00456598;</span></p>  <p><span style=\"font-family: gulimChe;\">ALTER TABLE TS02_SMB_ITEMS_RELATION DROP CONSTRAINT SYS_C00456599;</span></p>  <p><span style=\"font-family: gulimChe;\"><br></span></p>  <p><span style=\"font-family: gulimChe;\">ALTER TABLE TS02_SMB_SALES_TYPE_RELATION DROP CONSTRAINT SYS_C00456617;</span></p>  <p><span style=\"font-family: g",
			"NTT_CNTS_DESC": "ulimChe;\">ALTER TABLE TS02_SMB_SALES_TYPE_RELATION DROP CONSTRAINT SYS_C00456618;</span></p>  <p><span style=\"font-family: gulimChe;\"><br></span></p>  <p><span style=\"font-family: gulimChe;\">-- 2016.10.14 전상우GJ 요청</span></p>  <p><span style=\"font-family: gulimChe;\">CREATE OR REPLACE VIEW KAIS.VH01_DEPT_HIST</span></p>  <p><span style=\"font-family: gulimChe;\">AS</span></p>  <p><span style=\"font-family: gulimChe;\">WITH T AS (</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; SELECT</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; &nbsp; CT.REMARK6 AS COMP</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , DT.DEPT AS DEPT_CD</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , DT.FULL_DEPT_NM AS DEPT_NM</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , DT.DEPT_NM_ENG</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , (SELECT DEPT FROM TH01_DEPT WHERE SEQ_DEPT = OG.UP_SEQ_DEPT) AS UPPER_DEPT</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , SYS_CONNECT_BY_PATH(LPAD(TO_CHAR(OG.LEVEL_SEQ),3,'0'),'|') AS SORT_KEY</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , DT.FROM_DATE</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , DT.TO_DATE</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , ROW_NUMBER() OVER(PARTITION BY DT.DEPT, DT.FROM_DATE ORDER BY DT.TO_DATE DESC) AS RK</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; &nbsp; , 'Y' AS USE_YN</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; FROM TH01_DEPT DT</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; LEFT JOIN TH01_ORGAN OG ON DT.SEQ_DEPT = OG.SEQ_DEPT</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; LEFT JOIN TC00_CODE_LIST CT ON CT.CODE_GROUP='CORP' AND CT.CODE_NM = DT.CORP &nbsp;</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; WHERE 1=1</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; AND DT.DEPT IS NOT NULL</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; AND DT.FROM_DATE &lt; DT.TO_DATE</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; AND DT.CORP IN ('(주)TEST','Europe','Basildon','(America)')</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; START WITH OG.UP_SEQ_DEPT IS NULL</span></p>  <p><span style=\"font-family: gulimChe;\">&nbsp; CONNECT BY OG.UP_SEQ_DEPT = PRIOR OG.SEQ_DEPT</span></p>  <p><span style=\"font-family: gulimChe;\">)</span></p>  <p><span style=\"font-family: gulimChe;\">SELECT COMP, DEPT_CD, DEPT_NM, DEPT_NM_ENG, UPPER_DEPT, REPLACE(SORT_KEY &nbsp;,'|','') AS SORT_KEY, FROM_DATE, TO_DATE, USE_YN FROM T</span></p>  <p><span style=\"font-family: gulimChe;\">WHERE DEPT_CD NOT IN (SELECT DISTINCT DEPT_CD FROM T WHERE RK &gt; 1)</span></p>  <p><span style=\"font-family: gulimChe;\">UNION ALL</span></p>  <p><span style=\"font-family: gulimChe;\">SELECT COMP, DEPT_CD, MAX(DEPT_NM) AS DEPT_NM, DEPT_NM_ENG, UPPER_DEPT, REPLACE(SORT_KEY &nbsp;,",
